const SRC_IR_LZD_FRAME_STORE_DISJOINT: &str = "def ir_lzd_frame_store_disjoint (mem : IRList IRMemSlot) (n : Nat) (a : Nat) (v : IRScalar) (hdis : forall (x : Nat), Eq Bool (ir_nat_ltb x n) Bool.true -> Eq Bool (ir_nat_eqb a x) Bool.false) (s : IRScalar) (l : Level) (d : EncodesLevelArcD mem n s l) : EncodesLevelArcD (ir_mem_update mem a v) n s l := ir_lzd_frame_agree mem (ir_mem_update mem a v) n n (fun (x : Nat) (h : Eq Bool (ir_nat_ltb x n) Bool.true) => h) (fun (x : Nat) (h : Eq Bool (ir_nat_ltb x n) Bool.true) => ir_mem_lookup_update_skip mem a x v (hdis x h)) s l d";

